def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

Also keep a record of any content digests different from those in the root inventory
so that we can also check them when validating the content.

version_dirs is an array of version directory names and is assumed to be in
version sequence (1, 2, 3...).
    """
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    prior_manifest_digests = {}
    prior_fixity_digests = {}

    # Get root inventory's manifest and fixity for comparison
    root_manifest = {}
    root_fixity = {}
    if self.root_inv_validator is not None:
        root_manifest = getattr(self.root_inv_validator, 'manifest', {}) or {}
        root_fixity = getattr(self.root_inv_validator, 'fixity', {}) or {}

    for version_dir in version_dirs:
        inv_path = version_dir + '/inventory.json'
        if not self.obj_fs.exists(inv_path):
            self.log.error('E043', version=version_dir)
            continue

        try:
            inventory, inv_validator = self.validate_inventory(
                inv_path, where=version_dir)
        except ValidatorAbortException:
            continue

        # Validate the inventory digest file for this version
        if inv_validator.digest_algorithm:
            self.validate_inventory_digest(
                inv_path, inv_validator.digest_algorithm, where=version_dir)

        # Track manifest digests that differ from root inventory
        version_manifest = getattr(inv_validator, 'manifest', {}) or {}
        for digest, paths in version_manifest.items():
            if digest not in root_manifest:
                if version_dir not in prior_manifest_digests:
                    prior_manifest_digests[version_dir] = {}
                if digest not in prior_manifest_digests[version_dir]:
                    prior_manifest_digests[version_dir][digest] = {}
                for path in paths:
                    prior_manifest_digests[version_dir][digest][path] = [version_dir]

        # Track fixity digests that differ from root inventory
        version_fixity = getattr(inv_validator, 'fixity', {}) or {}
        for algorithm, digest_map in version_fixity.items():
            root_algo_fixity = root_fixity.get(algorithm, {})
            for digest, paths in digest_map.items():
                if digest not in root_algo_fixity:
                    if algorithm not in prior_fixity_digests:
                        prior_fixity_digests[algorithm] = {}
                    if digest not in prior_fixity_digests[algorithm]:
                        prior_fixity_digests[algorithm][digest] = {}
                    for path in paths:
                        prior_fixity_digests[algorithm][digest][path] = [version_dir]

    return (prior_manifest_digests, prior_fixity_digests)

