def next_version(version):
    """
    Next version identifier following existing pattern.

Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise Exception("Version must be a string")
    m = re.match(r'^v(\d+)$', version)
    if not m:
        raise Exception("Version must match pattern v<digits>")
    num_str = m.group(1)
    width = len(num_str)
    next_num = int(num_str) + 1
    if num_str[0] == '0':
        # Zero-padded: next version must still fit with a leading zero
        if len(str(next_num)) >= width:
            raise Exception("Version overflow")
        return 'v' + str(next_num).zfill(width)
    return 'v' + str(next_num)

