    """
    Casts arguments to correct types by modifying values_dict param.

By default all the values are strings.

:param parser_name: The command name, e.g. main, virsh, ospd, etc
:param values_dict: The dict of with arguments
    """
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    option_specs = self.spec_helper.get_parser_option_specs(parser_name)

    def cast_value(value, arg_type):
        if value is None:
            return value
        if not isinstance(value, str):
            return value
        try:
            if arg_type is bool:
                return value.lower() in ('true', 'yes', '1', 'on')
            elif arg_type is int:
                return int(value)
            elif arg_type is float:
                return float(value)
            elif arg_type is str:
                return value
            else:
                return arg_type(value)
        except (ValueError, TypeError):
            return value

    for arg_name in list(values_dict.keys()):
        if arg_name not in option_specs:
            continue

        option_spec = option_specs[arg_name]
        arg_type = option_spec.get('type', str)

        # Skip complex types - they are resolved later by resolve_custom_types
        if isinstance(arg_type, str) and arg_type in COMPLEX_TYPES:
            continue

        arg_value = values_dict[arg_name]

        if isinstance(arg_value, list):
            values_dict[arg_name] = [
                cast_value(val, arg_type) for val in arg_value
            ]
        else:
            values_dict[arg_name] = cast_value(arg_value, arg_type)

