            elif arg_type is str:
                return value
            else:
                return arg_type(value)
        except (ValueError, TypeError):
            return value

    for arg_name in list(values_dict.keys()):
        if arg_name not in option_specs:
            continue

        option_spec = option_specs[arg_name]
        arg_type = option_spec.get('type', str)

        # Skip complex types - they are resolved later by resolve_custom_types
        if isinstance(arg_type, str) and arg_type in COMPLEX_TYPES:
            continue

        arg_value = values_dict[arg_name]

        if isinstance(arg_value, list):
            values_dict[arg_name] = [
                cast_value(val, arg_type) for val in arg_value
            ]
        else:
            values_dict[arg_name] = cast_value(arg_value, arg_type)

