def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    from xrd import XRD
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    default = {"hcard_url": None}

    if not document:
        return default

    # Try to parse as JSON first (new format)
    try:
        data = json.loads(document)
        if isinstance(data, dict) and "links" in data:
            for link in data["links"]:
                if (isinstance(link, dict) and 
                    link.get("rel") == "http://microformats.org/profile/hcard" and
                    link.get("type") == "text/html" and
                    "href" in link):
                    return {"hcard_url": link["href"]}
        return default
    except (json.JSONDecodeError, TypeError, ValueError):
        pass

    # Try to parse as XML/XRD (old format)
    try:
        xrd = XRD.parse_xrd(document)
        for link in xrd.links:
            if (link.rel == "http://microformats.org/profile/hcard" and
                link.type == "text/html" and
                link.href):
                return {"hcard_url": link.href}
        return default
    except Exception:
        pass

    # If both parsing methods fail, return default
    return default

